<?php
declare(strict_types=1);

namespace Samla\Core\Identity;

use Samla\PluginApi\{AccessDenied, AuthorizationChecker, AuthorizationRequest, Decision, GroupDetailsChange, MutationContext, MutationRunner, Scope};

/** Public creation and optimistic rename of group metadata; membership and role identifiers stay fixed. */
final readonly class GroupDetailsService
{
    public function __construct(private PdoIdentityRepository $identities, private AuthorizationChecker $authorization,
        private MutationRunner $mutations) {}

    /** New identifier is generated by the service. Names are labels and need not be unique. */
    public function create(string $actorId, string $name): string
    {
        $id = 'grp.' . bin2hex(random_bytes(16));
        $this->change($actorId, $id, new GroupDetailsChange($name));
        return $id;
    }
    public function rename(string $actorId, string $groupId, string $expectedName, string $name): bool
    { return $this->change($actorId, $groupId, new GroupDetailsChange($name, $expectedName)); }

    private function change(string $actorId, string $groupId, GroupDetailsChange $change): bool
    {
        $context = new MutationContext(bin2hex(random_bytes(16)), $actorId,
            $change->expectedName === null ? 'identity.group.create' : 'identity.group.rename', Scope::Global, null,
            ['group' => $groupId], $change);
        $continuity = new AdministrationAccessGuard($this->identities, $this->authorization);
        $protected = null;
        $guard = function () use ($actorId, $continuity, &$protected): void {
            if ($this->authorization->decide(new AuthorizationRequest($actorId,
                'identity.groups.details.manage', Scope::Global))->decision !== Decision::Permit) { throw new AccessDenied(); }
            // Capture before validators, so their changes cannot erase a pre-existing administrative capability.
            $protected ??= $continuity->snapshot();
        };
        return $this->mutations->run($context, $guard, function () use ($groupId, $change, $continuity, &$protected): bool {
            $changed = $this->identities->changeGroupDetailsInsideTransaction($groupId, $change);
            $continuity->assertPreserved($protected);
            return $changed;
        });
    }
}
